    /// * `pipe` - Pipe used to transfer data.
    ///
    /// * `ashmem` - Shared memory, which can be obtained through `OH_DDK_CreateAshmem`.
    ///
    /// # Returns
    ///
    /// * [`USB_DDK_SUCCESS`](crate::UsbDdkErrCode::USB_DDK_SUCCESS): The operation is successful.
    /// [`USB_DDK_NO_PERM`](crate::UsbDdkErrCode::USB_DDK_NO_PERM): The permission check fails.
    /// [`USB_DDK_INVALID_OPERATION`](crate::UsbDdkErrCode::USB_DDK_INVALID_OPERATION): The USB DDK service connection fails.
    /// [`USB_DDK_INVALID_PARAMETER`](crate::UsbDdkErrCode::USB_DDK_INVALID_PARAMETER): The input **pipe** or **ashmem** is a null pointer, or the **ashmem** address
    /// is null.
    /// [`USB_DDK_MEMORY_ERROR`](crate::UsbDdkErrCode::USB_DDK_MEMORY_ERROR): The attempt to copy the memory that stores the read data fails.
    /// [`USB_DDK_IO_FAILED`](crate::UsbDdkErrCode::USB_DDK_IO_FAILED): An I/O exception occurs.
    /// [`USB_DDK_TIMEOUT`](crate::UsbDdkErrCode::USB_DDK_TIMEOUT): The operation times out.
    ///
    /// Available since API-level: 12
    #[cfg(feature = "api-12")]
    #[cfg_attr(docsrs, doc(cfg(feature = "api-12")))]
    pub fn OH_Usb_SendPipeRequestWithAshmem(
        pipe: *const UsbRequestPipe,
        ashmem: *mut DDK_Ashmem,
    ) -> i32;
    /// Creates a buffer. To avoid resource leakage, use [`OH_Usb_DestroyDeviceMemMap`](crate::OH_Usb_DestroyDeviceMemMap) to destroy a buffer after
    /// use.
    ///
    ///
    /// Required Permissions: ohos.permission.ACCESS_DDK_USB
    /// # Arguments
    ///
    /// * `deviceId` - Device ID.
    ///
    /// * `size` - Buffer size.
    ///
    /// * `devMmap` - Data memory map, through which the created buffer is returned to the caller.
    ///
    /// # Returns
    ///
    /// * [`USB_DDK_SUCCESS`](crate::UsbDdkErrCode::USB_DDK_SUCCESS): The operation is successful.
    /// [`USB_DDK_NO_PERM`](crate::UsbDdkErrCode::USB_DDK_NO_PERM): The permission check fails.
    /// [`USB_DDK_INVALID_PARAMETER`](crate::UsbDdkErrCode::USB_DDK_INVALID_PARAMETER): The input parameter **devMmap** or ***devMmap** is a null pointer.
    /// [`USB_DDK_MEMORY_ERROR`](crate::UsbDdkErrCode::USB_DDK_MEMORY_ERROR): The memory mapping fails, or the memory allocation of **devMmap** fails.
    ///
    /// Available since API-level: 10
    ///
    /// Version: 1.0
    pub fn OH_Usb_CreateDeviceMemMap(
        deviceId: u64,
        size: usize,
        devMmap: *mut *mut UsbDeviceMemMap,
    ) -> i32;
    /// Destroys a buffer. To prevent resource leakage, destroy a buffer in time after use.
    ///
    ///
    /// Required Permissions: ohos.permission.ACCESS_DDK_USB
    /// # Arguments
    ///
    /// * `devMmap` - Destroys the buffer created by calling [`OH_Usb_CreateDeviceMemMap`](crate::OH_Usb_CreateDeviceMemMap).
    ///
    /// Available since API-level: 10
    ///
    /// Version: 1.0
    pub fn OH_Usb_DestroyDeviceMemMap(devMmap: *mut UsbDeviceMemMap);
    /// Obtains the USB device ID list. Ensure that the pointer parameters passed in are valid. To avoid excessive
    /// memory usage, the size of the requested device ID array is recommended not to exceed 128. After using the struct,
    /// release the memory of its members; otherwise, resource leaks may occur. Besides, make sure that the obtained USB
    /// device ID has been filtered by **vid** in the driver configuration information.
    ///
    ///
    /// Required Permissions: ohos.permission.ACCESS_DDK_USB
    /// # Arguments
    ///
    /// * `devices` - Device memory address, which is used to store the obtained device ID list and quantity.
    ///
    /// # Returns
    ///
    /// * [`USB_DDK_SUCCESS`](crate::UsbDdkErrCode::USB_DDK_SUCCESS): The operation is successful.
    /// [`USB_DDK_NO_PERM`](crate::UsbDdkErrCode::USB_DDK_NO_PERM): The permission check fails.
    /// [`USB_DDK_INVALID_OPERATION`](crate::UsbDdkErrCode::USB_DDK_INVALID_OPERATION): The USB DDK service connection fails.
    /// [`USB_DDK_INVALID_PARAMETER`](crate::UsbDdkErrCode::USB_DDK_INVALID_PARAMETER): The input **devices** is a null pointer.
    ///
    /// Available since API-level: 18
    #[cfg(feature = "api-18")]
    #[cfg_attr(docsrs, doc(cfg(feature = "api-18")))]
    pub fn OH_Usb_GetDevices(devices: *mut Usb_DeviceArray) -> i32;
    /// Performs a USB control transfer. This API works in a synchronous manner.
    ///
    ///
    /// Required Permissions: ohos.permission.ACCESS_DDK_USB
    /// # Arguments
    ///
    /// * `deviceID` - An ID for the device to communicate with
    ///
    /// * `setupPacket` - Configuration parameters for the setup packet in control transfer requests
    ///
    /// * `data` - A suitably-sized data buffer for either input or output based on the direction bits
    /// within bmRequestType.
    ///
    /// * `timeout` - Timeout (in milliseconds) that this function should wait before giving up due to no response being
    /// received. For an unlimited timeout, use value 0.
    ///
    /// # Returns
    ///
    /// * on success, the number of bytes actually transferred.
    /// [`USB_DDK_NO_PERM`](crate::UsbDdkErrCode::USB_DDK_NO_PERM) Permission authentication failed.
    /// [`USB_DDK_INVALID_OPERATION`](crate::UsbDdkErrCode::USB_DDK_INVALID_OPERATION) DDK Service not initialized. Please invoke [`OH_Usb_Init`](crate::OH_Usb_Init) to complete the
    /// initialization process first.
    /// [`USB_DDK_INVALID_PARAMETER`](crate::UsbDdkErrCode::USB_DDK_INVALID_PARAMETER) The setupPacket or data parameters are invalid.
    /// [`USB_DDK_TIMEOUT`](crate::UsbDdkErrCode::USB_DDK_TIMEOUT) The control transfer timed out.
    /// [`USB_DDK_IO_FAILED`](crate::UsbDdkErrCode::USB_DDK_IO_FAILED) Control transfer request I/O exception.
    ///
    /// Available since API-level: 26
    #[cfg(feature = "api-26")]
    #[cfg_attr(docsrs, doc(cfg(feature = "api-26")))]
    pub fn OH_Usb_ControlTransfer(
        deviceID: u64,
        setupPacket: *const UsbControlRequestSetup,
        data: *mut u8,
        timeout: u32,
    ) -> i32;
    /// Queries and returns the list of non-root hubs. Ensure that the pointer parameters passed in are valid. To
